definition.script:
pipeline {
  agent { label 'controller' }

  options {
    timestamps()
    disableConcurrentBuilds()
  }

  stages {
    stage('Curate Data Dictionaries (fully compliant studies)') {
      steps {
        withAWS(role: 'dbgap-etl', roleAccount: '736265540791', duration: 3600, roleSessionName: 'subject-multi-pipeline') {
          s3Download(
            file: 'Managed_Inputs.csv',
            bucket: 'avillach-73-bdcatalyst-etl',
            path: 'general/resources/Managed_Inputs.csv',
            force: true
          )
        }

        script {
          def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
          def importRuns = [:]

          inputs.each { row ->
            def ready     = (row['Data is ready to process'] ?: '').trim()
            def processed = (row['Data Processed'] ?: '').trim()
            def hasMulti  = (row['Has Multi'] ?: '').trim()
            def studyType = (row['Study Type'] ?: '').trim()

            def stdyId = (row['Study Identifier'] ?: '').trim()
            def abv    = (row['Study Abbreviated Name'] ?: '').trim()

            def typeEligible =
              studyType.equalsIgnoreCase('compliant') ||
              studyType.equalsIgnoreCase('topmed') ||
              studyType.equalsIgnoreCase('parent') ||
              studyType.equalsIgnoreCase('substudy')

            def shouldRun = (ready == 'Yes') && (processed == 'No') && (hasMulti == 'Yes') && typeEligible

            if (shouldRun && stdyId) {
              def sid = stdyId
              def sabv = abv
              importRuns["curate_${sid}"] = {
                build job: 'Curation - Compliant Data Dictionary to Metadata',
                  parameters: [
                    string(name: 'study_abv', value: sabv),
                    string(name: 'study_id',  value: sid)
                  ],
                  wait: true,
                  propagate: true
              }
            }
          }

          if (importRuns.isEmpty()) {
            echo "No eligible studies found."
            return
          }

          echo "Launching ${importRuns.size()} parallel jobs on controller..."
          parallel importRuns
        }
      }
    }
  }
}
